import SwiftUI

/// The Marquee illustrations (docs/IOS-DELIGHT-PLAN.md section 5.2): bold flat
/// shapes and art-deco sunbursts, drawn for empty screens and the champion card.
///
/// Each piece is two or three layers (`Assets.xcassets/Marquee`) that share one
/// 240 × 132 canvas, so stacking them rebuilds the drawing and each layer can be
/// moved on its own when the piece arrives. Every layer has a light and a dark
/// SVG. The art is regenerated by `apps/ios/docs/marquee/generate.mjs`; never edit
/// the SVGs by hand.
///
/// Rules: one fixed size on every iPhone (never stretched to the screen); only on
/// the screens the plan lists, and gone once the screen has content; never beside
/// real movie posters; hidden from VoiceOver, since the title and message beside
/// it say everything.
nonisolated enum MarqueeIllustration: String, CaseIterable, Sendable {
    /// I1 · Trades, empty.
    case trades
    /// I2 · Wishlist, empty (mine and league-mates).
    case wishlist
    /// I3 · Bids, empty; bid history, empty.
    case bids
    /// I4 · Notifications, empty.
    case notifications
    /// I5 · Draft before it starts; roster before the draft.
    case draft
    /// I6 · No leagues yet; season not open.
    case entrance
    /// I7 · Season complete, behind the champion card.
    case champion

    /// The layers, back to front, as asset catalog names.
    var layers: [String] {
        let parts: [String] = switch self {
        case .trades: ["Left", "Right", "Arrows"]
        case .wishlist: ["Back", "Front", "Heart"]
        case .bids: ["Card", "Slip", "Coin"]
        case .notifications: ["Crest", "Board", "Bulbs"]
        case .draft: ["Seats", "Ticket"]
        case .entrance: ["Building", "Canopy", "Doors"]
        case .champion: ["Sunburst", "Card", "Stars"]
        }
        let piece = rawValue.prefix(1).uppercased() + rawValue.dropFirst()
        return parts.map { "Marquee/\(piece)\($0)" }
    }

    /// The width the plan sets: 216 pt for empty screens, 200 pt for the champion.
    var width: CGFloat { self == .champion ? 200 : 216 }

    /// Every piece is drawn on a 240 × 132 canvas.
    static let aspectRatio: CGFloat = 240.0 / 132.0
}

/// A Marquee illustration at its fixed size, its layers stacked.
struct MarqueeArt: View {
    let illustration: MarqueeIllustration
    var width: CGFloat?

    init(_ illustration: MarqueeIllustration, width: CGFloat? = nil) {
        self.illustration = illustration
        self.width = width
    }

    var body: some View {
        let width = width ?? illustration.width
        ZStack {
            ForEach(illustration.layers, id: \.self) { layer in
                Image(layer)
                    .resizable()
                    .scaledToFit()
            }
        }
        .frame(width: width, height: width / MarqueeIllustration.aspectRatio)
        .accessibilityHidden(true)
    }
}

