/// Every Marquee piece at its real size, captioned, on the page background;
/// the champion also on the champion card's gold tint. For previews and the
/// `marqueeEmpty` / `marqueeMoments` screenshot scenes.
struct MarqueeGallery: View {
    let pieces: [MarqueeIllustration]

    var body: some View {
        ScrollView {
            VStack(spacing: 18) {
                ForEach(pieces, id: \.self) { piece in
                    VStack(spacing: 6) {
                        if piece == .champion {
                            MarqueeArt(piece)
                                .padding(.vertical, 14)
                                .frame(maxWidth: .infinity)
                                .frCardBackground(.gold)
                        } else {
                            MarqueeArt(piece)
                        }
                        Text(piece.rawValue.capitalized)
                            .frFont(.caption)
                            .foregroundStyle(Color.frTextSecondary)
                    }
                }
            }
            .padding(FRMetrics.pageMargin)
            .frame(maxWidth: .infinity)
        }
        .background(Color.frBackground)
    }
}
#endif
